-- Hosbah queries.

-- name: ListVolumesOfApp :many
-- Team scope (and the deploy pipeline, system + team): an app's volumes, by name.
SELECT * FROM app_volumes WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') ORDER BY name, id;

-- name: VolumeOfApp :one
-- Team scope: one volume of an app, by id or by name.
SELECT * FROM app_volumes
WHERE app_id = sqlc.arg('app_id') AND team_id = sqlc.arg('team_id') AND (id = sqlc.arg('ref')::text OR name = sqlc.arg('ref')::text)
ORDER BY (id = sqlc.arg('ref')::text) DESC LIMIT 1;

-- name: InsertAppVolume :one
INSERT INTO app_volumes (team_id, app_id, name, mount_path)
VALUES (sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('name'), sqlc.arg('mount_path'))
RETURNING *;

-- name: DeleteAppVolumeInTeam :execrows
DELETE FROM app_volumes WHERE id = sqlc.arg('id') AND team_id = sqlc.arg('team_id');

-- name: TeamVolumes :many
-- Team scope: every volume of the team's apps with its app and server, for the team Storage page.
SELECT v.id, v.name, v.mount_path, v.created_at, a.id AS app_id, a.name AS app_name, a.server_id
FROM app_volumes v JOIN apps a ON a.id = v.app_id
WHERE v.team_id = sqlc.arg('team_id')
ORDER BY a.name, v.name;
